      { label: "\uC7AC\uD65C\uC131\uD654", value: "60\u201390\u2103 1\u20132\uC2DC\uAC04", enLabel: "Regeneration", enValue: "60\u201390\u2103 \xB7 1\u20132h", jaLabel: "\u518D\u6D3B\u6027\u5316", jaValue: "60\u201390\u2103 \xB7 1\u20132\u6642\u9593" }
