    "\u6BD4\u8868\u9762\u7A4D650\u2013800 m\xB2/g \xB7 \u4E7E\u71E5\u30FB\u9632\u6E7F\u6A19\u6E96\u54C1",
    "SL-DES-01\uC740 \uD22C\uBA85 \uB610\uB294 \uBC18\uD22C\uBA85 \uC720\uB9AC\uC9C8\uC758 \uAD6C\uD615(\uD3A0\uB9BF) \uB610\uB294 \uAD34\uC0C1 \uC2E4\uB9AC\uCE74\uAC94\uC785\uB2C8\uB2E4. \uD3C9\uADE0 \uACF5\uACBD 2.0\u20133.0 nm, \uBE44\uD45C\uBA74\uC801 650\u2013800 m\xB2/g\uB85C \uAC74\uC870\xB7\uBC29\uC2B5\uC774 \uC8FC\uB41C \uC6A9\uB3C4\uC774\uBA70, \uCD09\uB9E4\uB2F4\uCCB4\xB7\uD761\uCC29\uC81C\xB7\uBD84\uB9AC\uC81C\xB7\uBCC0\uC555\uD761\uCC29(PSA) \uC6A9\uB3C4\uB85C\uB3C4 \uC0AC\uC6A9\uB429\uB2C8\uB2E4.",
