    "SL-CT-601\u306F45\u03BCm\u7C97\u7C92\u30FB\u591A\u5B54\u6027\u306E\u6C88\u964D\u30B7\u30EA\u30AB\u3067\u3001\u98FC\u6599\u6DFB\u52A0\u5264\u30FB\u8FB2\u85AC\u539F\u4F53\u30FB\u9676\u78C1\u5668\u91C9\u85AC\u306E\u62C5\u4F53(carrier)\u304A\u3088\u3073\u5145\u586B\u5264\u3068\u3057\u3066\u4F7F\u7528\u3055\u308C\u307E\u3059\u3002BET 220\u2013250 m\xB2/g\u3001DBP 310\u2013370\u306B\u3088\u308A\u6709\u52B9\u6210\u5206\u306E\u5747\u4E00\u62C5\u6301\u3068\u5F90\u653E\u52B9\u679C\u3092\u4ED8\u4E0E\u3057\u3001\u53D6\u308A\u6271\u3044\u6027\u306B\u512A\u308C\u308B\u7C97\u7C92\u578B\u3067\u3059\u3002",
