    "SL-CT-MB-107\u306FPP\u30FBPE\u30D5\u30A3\u30EB\u30E0\u30FB\u30B7\u30FC\u30C8\u7528\u6A5F\u80FD\u6027\u30DE\u30B9\u30BF\u30FC\u30D0\u30C3\u30C1\u5C02\u7528\u306E\u6C88\u964D\u30B7\u30EA\u30AB\u3067\u3059\u3002SiO\u2082 \u2265 99%\u9AD8\u7D14\u5EA6\u3001BET 280\u2013300 m\xB2/g\u3001DBP 170\u2013180\u3001<5\u03BCm\u306E\u5FAE\u7D30\u7C92\u5EA6\u3067\u30A2\u30F3\u30C1\u30D6\u30ED\u30C3\u30AD\u30F3\u30B0\u30FB\u30DE\u30C3\u30C8\u30FB\u900F\u660E\u30D5\u30A3\u30EB\u30E0\u6539\u8CEA\u306B\u6700\u9069\u5316\u3055\u308C\u3066\u304A\u308A\u3001\u6A39\u8102\u5185\u5747\u4E00\u5206\u6563\u3068\u4F4E\u30B2\u30EB\u30FB\u6B20\u9665\u7387\u3092\u4FDD\u8A3C\u3057\u307E\u3059\u3002",
